'use server'

import { cookies } from 'next/headers'
import { refresh } from 'next/cache'

export async function toggleNotificationPreference() {
  const cookieStore = await cookies()
  const current = cookieStore.get('notifications-enabled')?.value === 'true'
  const updated = !current

  cookieStore.set('notifications-enabled', String(updated))

  refresh()
}

import { cookies } from 'next/headers'
import { toggleNotificationPreference } from './actions'

export default async function Home() {
  const cookieStore = await cookies()
  const notificationsEnabled =
    cookieStore.get('notifications-enabled')?.value === 'true'

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently:{' '}
        <strong>{notificationsEnabled ? 'On' : 'Off'}</strong>
      </p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          Turn {notificationsEnabled ? 'Off' : 'On'}
        </button>
      </form>
    </main>
  )
}
